const path = require('path');

// 1. Safely glueing paths together
// If running on Windows, this outputs: folder\subfolder\file.txt
// If running on Mac/Linux, outputs: folder/subfolder/file.txt
const safePath = path.join('folder', 'subfolder', 'file.txt');
console.log("Joined Path:", safePath);

// 2. Getting file info
const filePath = '/var/www/website/index.html';

console.log("Base name:", path.basename(filePath)); // 'index.html'
console.log("Extension:", path.extname(filePath));  // '.html'
console.log("Directory:", path.dirname(filePath));  // '/var/www/website'

// 3. Creating an Absolute Path (Resolves relative to your current working directory)
const absolute = path.resolve('public', 'css', 'style.css');
console.log("Absolute Path:", absolute);
